//! `POST /game/token` (#151) through the real handler. Configuration and the
//! refusals decided before the session read need no database; the rest
//! return early unless `AUTHNZ_TEST_DYNAMODB_ENDPOINT` is set, as CI's
//! `test` job sets it. Every key here is generated by the test that uses it.

use super::*;
use crate::db::{DynamoDBStore, Session, SessionOpened};
use crate::test_helpers::{build_test_app_state, build_test_app_state_with_store};
use authnz_rs::cwt::CwtError;
use axum::body::Body;
use axum::http::{HeaderMap, Request};
use axum::routing::post;
use axum::{Extension, Router};
use base64::Engine;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use p256::ecdsa::signature::Signer;
use p256::ecdsa::{Signature, SigningKey};
use p256::elliptic_curve::rand_core::OsRng;
use serde_json::{Value, json};
use std::sync::Arc;
use tower::ServiceExt;

const AUDIENCE: &str = "https://game.example";
const OTHER_AUDIENCE: &str = "https://other-game.example";

fn configured(lifetime: i64) -> Arc<GameTokens> {
    Arc::new(GameTokens {
        audiences: vec![AUDIENCE.into(), OTHER_AUDIENCE.into()],
        lifetime_seconds: lifetime,
        mints: Mutex::default(),
    })
}

/// A device: the Secure Enclave key a session is opened with.
struct Device(SigningKey);

impl Device {
    fn new() -> Self {
        Self(SigningKey::random(&mut OsRng))
    }

    fn public_key(&self) -> Vec<u8> {
        self.0
            .verifying_key()
            .to_encoded_point(false)
            .as_bytes()
            .to_vec()
    }

    fn sign(&self, message: &str) -> String {
        let sig: Signature = self.0.sign(message.as_bytes());
        URL_SAFE_NO_PAD.encode(sig.to_bytes())
    }

    /// A well-formed request for `session` and `audience`, signed now.
    fn request(&self, session: &Uuid, audience: &str) -> Value {
        self.request_at(session, audience, Utc::now().timestamp())
    }

    fn request_at(&self, session: &Uuid, audience: &str, issued_at: i64) -> Value {
        json!({
            "sessionId": session,
            "audience": audience,
            "issuedAt": issued_at,
            "signature": self.sign(&game_token::mint_message(session, audience, issued_at)),
        })
    }
}

async fn post_token(state: &AppState, body: Value) -> (StatusCode, HeaderMap, Value) {
    let app = Router::new()
        .route("/game/token", post(token_handler))
        .layer(Extension(state.clone()));
    let req = Request::post("/game/token")
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .unwrap();
    let resp = app.oneshot(req).await.unwrap();
    let (status, headers) = (resp.status(), resp.headers().clone());
    let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    (status, headers, serde_json::from_slice(&bytes).unwrap())
}

// --------- Configuration ---------

#[test]
fn config_is_off_by_default_and_parses_a_list() {
    let off = GameTokens::parse(None, None, &[]).unwrap();
    assert!(off.audiences.is_empty());
    assert_eq!(off.lifetime_seconds, 900);
    assert!(
        GameTokens::parse(Some(" , "), None, &[])
            .unwrap()
            .audiences
            .is_empty()
    );

    let on = GameTokens::parse(
        Some(" https://game.example , https://other-game.example "),
        Some("600"),
        &["arkavo", "https://platform.example"],
    )
    .unwrap();
    assert_eq!(on.audiences, [AUDIENCE, OTHER_AUDIENCE]);
    assert_eq!(on.lifetime_seconds, 600);
}

#[test]
fn an_audience_another_token_carries_fails_startup() {
    let taken = [
        "arkavo",
        "https://platform.example",
        "https://agents.example",
    ];
    for bad in [
        "arkavo",
        "ARKAVO",
        "https://platform.example",
        "https://Platform.example/",
        "https://agents.example",
        "arkavo:devicecheck",
        "owner-kas:01JC0000000000000000000000",
        "Owner-KAS:x",
        "has space",
        "naïve",
    ] {
        let list = format!("{AUDIENCE},{bad}");
        assert!(
            GameTokens::parse(Some(&list), None, &taken).is_err(),
            "{bad:?}"
        );
    }
    assert!(GameTokens::parse(Some(&"a".repeat(129)), None, &taken).is_err());
    assert!(GameTokens::parse(Some(AUDIENCE), None, &taken).is_ok());

    // An OIDC client id, known only after the clients are loaded.
    let game = GameTokens::parse(Some("https://game.example,game-rp"), None, &taken).unwrap();
    assert!(
        game.refuse_client_ids(["opentdf", "Game-RP"].into_iter())
            .is_err()
    );
    assert!(game.refuse_client_ids(["opentdf"].into_iter()).is_ok());
}

#[test]
fn the_lifetime_is_bounded_to_an_hour() {
    let parse = |seconds| GameTokens::parse(Some(AUDIENCE), Some(seconds), &[]);
    assert_eq!(parse("60").unwrap().lifetime_seconds, 60);
    assert_eq!(parse("3600").unwrap().lifetime_seconds, 3600);
    assert_eq!(parse(" ").unwrap().lifetime_seconds, 900);
    for bad in ["59", "3601", "0", "-900", "fifteen", "900.0"] {
        assert!(parse(bad).is_err(), "{bad}");
    }
}

#[test]
fn the_limit_is_per_account_and_per_minute() {
    let game = configured(900);
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    for _ in 0..GAME_TOKEN_MINTS_PER_MINUTE {
        game.admit(&a, 1_000).unwrap();
    }
    assert_eq!(game.admit(&a, 1_010), Err(50));
    assert!(game.admit(&b, 1_010).is_ok());
    assert!(game.admit(&a, 1_060).is_ok());
}

// --------- Refusals decided before any read ---------

#[tokio::test]
async fn unconfigured_is_503() {
    let state = build_test_app_state().await;
    let device = Device::new();
    let (st, h, body) = post_token(&state, device.request(&Uuid::new_v4(), AUDIENCE)).await;
    assert_eq!(st, StatusCode::SERVICE_UNAVAILABLE);
    assert_eq!(body, json!({ "error": "game_tokens_unavailable" }));
    assert_eq!(h["cache-control"], "no-store");
}

#[tokio::test]
async fn malformed_requests_are_400_before_the_session_is_read() {
    // No database here: each 400 must be decided before the session read.
    let mut state = build_test_app_state().await;
    state.game = configured(900);
    let device = Device::new();
    let id = Uuid::new_v4();
    let good = device.request(&id, AUDIENCE);
    let with = |key: &str, value: Value| {
        let mut body = good.clone();
        body[key] = value;
        body
    };
    let without = |key: &str| {
        let mut body = good.clone();
        body.as_object_mut().unwrap().remove(key);
        body
    };
    let cases = [
        (json!("not an object"), "invalid_request"),
        (without("sessionId"), "invalid_request"),
        (without("signature"), "invalid_request"),
        (without("issuedAt"), "invalid_request"),
        (with("sessionId", json!("not-a-uuid")), "invalid_request"),
        // An integer only: no fraction, no exponent, no string.
        (with("issuedAt", json!(1_794_268_800.0)), "invalid_request"),
        (with("issuedAt", json!("1794268800")), "invalid_request"),
        (
            with("audience", json!("https://unlisted.example")),
            "invalid_audience",
        ),
        // Listed values are matched exactly.
        (
            with("audience", json!("https://GAME.example")),
            "invalid_audience",
        ),
        (
            with("audience", json!(format!("{AUDIENCE}/"))),
            "invalid_audience",
        ),
    ];
    for (body, error) in cases {
        let (st, h, got) = post_token(&state, body.clone()).await;
        assert_eq!(st, StatusCode::BAD_REQUEST, "{body}");
        assert_eq!(got, json!({ "error": error }), "{body}");
        assert_eq!(h["cache-control"], "no-store");
    }
}

/// A wrong clock is told apart from a dead session, with identity's time,
/// and without the session being read: the client corrects and retries
/// rather than spending a renewal.
#[tokio::test]
async fn a_clock_out_of_window_is_400_with_the_servers_time() {
    let mut state = build_test_app_state().await;
    state.game = configured(900);
    let device = Device::new();
    let id = Uuid::new_v4();
    for offset in [
        GAME_TOKEN_PROOF_SKEW_SECONDS + 5,
        -(GAME_TOKEN_PROOF_SKEW_SECONDS + 5),
        86_400,
    ] {
        let before = Utc::now().timestamp();
        let (st, _, body) =
            post_token(&state, device.request_at(&id, AUDIENCE, before + offset)).await;
        assert_eq!(st, StatusCode::BAD_REQUEST, "{offset}");
        assert_eq!(body["error"], "invalid_issued_at");
        let server = body["serverTime"].as_i64().unwrap();
        assert!((before..=before + 5).contains(&server), "{server}");
    }
}

// --------- Through the session (DynamoDB Local) ---------

struct Fixture {
    state: AppState,
    store: Arc<DynamoDBStore>,
    user: Uuid,
    handle: String,
    device: Device,
    session: Uuid,
}

impl Fixture {
    /// A live account with a session opened `age` seconds ago and last
    /// renewed `since_renewal` seconds ago.
    async fn new(age: i64, since_renewal: i64) -> Option<Self> {
        let store = Arc::new(crate::db::tests::local_store()?);
        let mut state = build_test_app_state_with_store(store.clone());
        state.game = configured(900);
        let name = format!("gt-{}", &Uuid::new_v4().simple().to_string()[..12]);
        let user = store
            .create_user(&name, "did:key:z6MkGameToken")
            .await
            .unwrap();
        let device = Device::new();
        let session = Uuid::new_v4();
        let now = Utc::now().timestamp();
        let row = Session {
            session_id: session,
            user_id: user.user_id,
            public_key: device.public_key(),
            assertion_at: now - age,
            last_renewed_at: now - since_renewal,
            generation: 1,
            credential_hash: vec![7; 32],
        };
        assert_eq!(
            store.open_session(&row, now).await.unwrap(),
            SessionOpened::Opened
        );
        Some(Self {
            state,
            store,
            user: user.user_id,
            handle: format!("{name}.arkavo.social"),
            device,
            session,
        })
    }

    async fn fresh() -> Option<Self> {
        Self::new(120, 60).await
    }

    async fn mint(&self, audience: &str) -> (StatusCode, HeaderMap, Value) {
        post_token(&self.state, self.device.request(&self.session, audience)).await
    }

    fn decode(&self, body: &Value, audience: &str) -> GameToken {
        let bytes = authnz_rs::cwt::decode_from_header(body["token"].as_str().unwrap()).unwrap();
        game_token::verify(
            &bytes,
            &self.state.cwt_keys,
            &self.state.issuer,
            audience,
            Utc::now().timestamp(),
            60,
        )
        .unwrap()
    }

    async fn unauthorized(&self, body: Value) {
        let (st, _, got) = post_token(&self.state, body.clone()).await;
        assert_eq!(st, StatusCode::UNAUTHORIZED, "{body}");
        assert_eq!(got, json!({ "error": "unauthorized" }), "{body}");
    }

    async fn stored(&self) -> Option<Session> {
        self.store.get_session(&self.session).await.unwrap()
    }
}

#[tokio::test]
async fn a_session_gets_a_token_bound_to_its_device_key() {
    let Some(f) = Fixture::fresh().await else {
        return;
    };
    let before = f.stored().await.unwrap();
    let now = Utc::now().timestamp();
    let (st, h, body) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(h["cache-control"], "no-store");
    assert_eq!(body["onlinePlay"], false);
    let server = body["serverTime"].as_i64().unwrap();
    assert!((now..=now + 5).contains(&server));

    let t = f.decode(&body, AUDIENCE);
    assert_eq!(t.iss, *f.state.issuer);
    assert_eq!(t.sub, f.user.to_string());
    assert_eq!(t.aud, AUDIENCE);
    assert_eq!(t.exp - t.iat, 900);
    assert_eq!(body["expiresAt"], json!(t.exp));
    assert_eq!(t.handle, f.handle);
    assert!(!t.online_play, "no pass: no entitlement claim");
    // cnf is the session's stored key, which the caller never sent.
    let key = f.device.public_key();
    assert_eq!(
        (t.x.as_slice(), t.y.as_slice()),
        (&key[1..33], &key[33..65])
    );

    // The device can prove possession to the game server with it.
    let text = body["token"].as_str().unwrap();
    let message = game_token::request_message(AUDIENCE, "POST", "/v1/runs", now, b"{}", text);
    assert!(game_token::request_proof_verifies(
        &t,
        text,
        "POST",
        "/v1/runs",
        b"{}",
        now,
        &f.device.sign(&message),
        now,
        60
    ));

    // The other listed audience gets its own token, refused at this one.
    let (st, _, other) = f.mint(OTHER_AUDIENCE).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(f.decode(&other, OTHER_AUDIENCE).aud, OTHER_AUDIENCE);
    let bytes = authnz_rs::cwt::decode_from_header(other["token"].as_str().unwrap()).unwrap();
    assert!(matches!(
        game_token::verify(
            &bytes,
            &f.state.cwt_keys,
            &f.state.issuer,
            AUDIENCE,
            now,
            60
        ),
        Err(CwtError::AudienceMismatch)
    ));
    // Identity itself never accepts a game token.
    let opts = authnz_rs::cwt::VerifyOptions {
        expected_iss: None,
        expected_aud: None,
        now,
        skew_secs: 60,
    };
    assert!(matches!(
        authnz_rs::cwt::verify(&bytes, &f.state.cwt_keys, &opts),
        Err(CwtError::Malformed)
    ));

    // The mint is not a renewal: the session row is untouched.
    assert_eq!(f.stored().await.unwrap(), before);
}

#[tokio::test]
async fn only_the_sessions_device_key_can_mint() {
    let Some(f) = Fixture::fresh().await else {
        return;
    };
    let thief = Device::new();
    // Another key, even one the caller offers as its own.
    f.unauthorized(thief.request(&f.session, AUDIENCE)).await;
    let mut offered = thief.request(&f.session, AUDIENCE);
    offered["cnf_key"] = json!(URL_SAFE_NO_PAD.encode(thief.public_key()));
    offered["publicKey"] = offered["cnf_key"].clone();
    f.unauthorized(offered).await;

    // The right key over another audience, time or session.
    let mut other_aud = f.device.request(&f.session, OTHER_AUDIENCE);
    other_aud["audience"] = json!(AUDIENCE);
    f.unauthorized(other_aud).await;
    let now = Utc::now().timestamp();
    let mut other_time = f.device.request_at(&f.session, AUDIENCE, now - 30);
    other_time["issuedAt"] = json!(now);
    f.unauthorized(other_time).await;
    f.unauthorized(f.device.request(&Uuid::new_v4(), AUDIENCE))
        .await;

    // A session message signed by the device is not a mint proof.
    let mut refresh = f.device.request(&f.session, AUDIENCE);
    refresh["signature"] = json!(f.device.sign(&format!(
        "arkavo-session-refresh-v1\n{}\n1.c2VjcmV0",
        f.session
    )));
    f.unauthorized(refresh).await;
    // A DER signature is not accepted.
    let mut der = f.device.request(&f.session, AUDIENCE);
    let sig: Signature = f.device.0.sign(
        game_token::mint_message(&f.session, AUDIENCE, der["issuedAt"].as_i64().unwrap())
            .as_bytes(),
    );
    der["signature"] = json!(URL_SAFE_NO_PAD.encode(sig.to_der().as_bytes()));
    f.unauthorized(der).await;

    // None of that ended the session: the device still mints.
    assert!(f.stored().await.is_some());
    assert_eq!(f.mint(AUDIENCE).await.0, StatusCode::OK);
}

#[tokio::test]
async fn an_over_or_idle_session_is_refused_and_never_ended_here() {
    // Past the 24 h deadline.
    let Some(f) = Fixture::new(SESSION_MAX_SECONDS + 1, 60).await else {
        return;
    };
    f.unauthorized(f.device.request(&f.session, AUDIENCE)).await;
    assert!(f.stored().await.is_some(), "the renewal route ends it");

    // Inside the deadline, idle past the limit.
    let f = Fixture::new(
        7_200 + SESSION_IDLE_LIMIT_SECONDS,
        SESSION_IDLE_LIMIT_SECONDS + 1,
    )
    .await
    .unwrap();
    f.unauthorized(f.device.request(&f.session, AUDIENCE)).await;
    assert!(f.stored().await.is_some());

    // Just inside both.
    let f = Fixture::new(7_200, SESSION_IDLE_LIMIT_SECONDS - 30)
        .await
        .unwrap();
    assert_eq!(f.mint(AUDIENCE).await.0, StatusCode::OK);
}

#[tokio::test]
async fn a_token_never_outlives_its_session() {
    // Five minutes of the session left: less than the 15-minute lifetime.
    let Some(f) = Fixture::new(SESSION_MAX_SECONDS - 300, 60).await else {
        return;
    };
    let deadline = f.stored().await.unwrap().assertion_at + SESSION_MAX_SECONDS;
    let (st, _, body) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::OK, "{body}");
    let t = f.decode(&body, AUDIENCE);
    assert_eq!(t.exp, deadline);
    assert!(t.exp - t.iat <= 300);
    assert_eq!(body["expiresAt"], json!(deadline));
}

#[tokio::test]
async fn a_deleted_accounts_session_cannot_mint() {
    let Some(f) = Fixture::fresh().await else {
        return;
    };
    f.store
        .tombstone_account(&f.user, &format!("{}.test", f.user), None, 1_700_000_000)
        .await
        .unwrap();
    f.unauthorized(f.device.request(&f.session, AUDIENCE)).await;
}

#[tokio::test]
async fn mints_past_the_limit_are_429_with_retry_after() {
    let Some(f) = Fixture::fresh().await else {
        return;
    };
    let now = Utc::now().timestamp();
    for _ in 0..GAME_TOKEN_MINTS_PER_MINUTE {
        f.state.game.admit(&f.user, now).unwrap();
    }
    let (st, h, body) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::TOO_MANY_REQUESTS);
    assert_eq!(body, json!({ "error": "rate_limited" }));
    let retry: u64 = h["retry-after"].to_str().unwrap().parse().unwrap();
    assert!((1..=60).contains(&retry), "{retry}");
    // A caller without the device key does not spend the account's budget:
    // the proof is checked first.
    let other = Fixture::fresh().await.unwrap();
    let thief = Device::new();
    for _ in 0..GAME_TOKEN_MINTS_PER_MINUTE + 5 {
        other
            .unauthorized(thief.request(&other.session, AUDIENCE))
            .await;
    }
    assert_eq!(other.mint(AUDIENCE).await.0, StatusCode::OK);
}

/// The pass rides in the token while the account holds it, and a mint right
/// after a payment asks the market again although "no term" was cached.
#[tokio::test]
async fn a_mint_carries_the_pass_once_it_is_paid() {
    let Some(mut f) = Fixture::fresh().await else {
        return;
    };
    let market = crate::market::subscription::tests::Harness::new().await;
    f.state.market = Arc::new(Some(market.source_for_state()));

    let (st, _, first) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::OK, "{first}");
    assert_eq!(first["onlinePlay"], false);
    assert!(!f.decode(&first, AUDIENCE).online_play);
    assert_eq!(market.hits(), 1);

    market.subscribe(&f.user);
    let (st, _, second) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::OK, "{second}");
    assert_eq!(second["onlinePlay"], true);
    assert!(f.decode(&second, AUDIENCE).online_play);
    assert_eq!(market.hits(), 2, "the mint rechecked the cached none");
}

/// Publishing is no part of a game token, even for an account that may
/// publish.
#[tokio::test]
async fn a_lifetime_member_gets_the_pass_and_no_other_entitlement() {
    use crate::app_store::{AppStoreApp, AppStoreConfig, Environment, Grant};
    use crate::db::{AppStoreRecord, GraceUpdate};
    const MEMBERSHIP: &str = "com.arkavo.ArkavoCreator.membership.monthly";
    const PASS: &str = "com.example.game.pass.monthly";

    let Some(mut f) = Fixture::fresh().await else {
        return;
    };
    let mut cfg = AppStoreConfig::for_tests(Vec::new());
    cfg.apps.push(AppStoreApp {
        bundle_id: "com.example.game".into(),
        app_apple_id: 4_242,
        products: HashMap::from([(PASS.to_string(), Grant::OnlinePlay)]),
        environments: [Environment::Production].into(),
    });
    f.state.app_store = Arc::new(Some(cfg));
    let now = Utc::now().timestamp();
    for product in [MEMBERSHIP, PASS] {
        let otid = Uuid::new_v4().as_u128().to_string();
        f.store
            .put_app_store_state(
                &f.user,
                &AppStoreRecord {
                    original_transaction_id: otid.clone(),
                    transaction_id: Some(otid),
                    product_id: product.into(),
                    environment: Environment::Production,
                    expires_at: now + 3600,
                    grace_expires_at: None,
                    revoked_at: None,
                    last_signed_at: now,
                },
                GraceUpdate::Keep,
            )
            .await
            .unwrap();
    }
    let (st, _, body) = f.mint(AUDIENCE).await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(body["onlinePlay"], true);
    // `verify` refuses any entitlement but the pass, so decoding at all
    // shows publishing is not there.
    assert!(f.decode(&body, AUDIENCE).online_play);
}
